// The fallback plates and the style references, pinned in the engine image (media/).
//   node scripts/plates.ts --placeholder "<source logo.mp4>"
//     PLACEHOLDERS (until the --live set replaces them): 24 plates (1536×864 JPEG) and 6 references (1024×1024 JPEG) cut
//     deterministically from frames of the particle-helix logo loop on the loop's own near-black (#020405). The manifest says
//     `placeholder: true`.
//   node scripts/plates.ts --live
//     The real set, once (OPENAI_API_KEY in the env, never an argument): 4 plates in each style but the meme (24),
//     generated by the studio's own generate() (src/studio.ts: the pinned model, the style bible, moderation, the
//     near-duplicate check, the rubric) with event-neutral helix scenes. Nothing is posted or sent: it talks to OpenAI
//     only. Its state (the round cap, near-duplicate hashes) lives in $TMPDIR/dna-plates, so a run that stops halfway
//     resumes: plates already written are kept. When all 24 exist it writes media/plates/plate-<style>-N.jpg, the
//     manifest (`placeholder: false`, each plate's sha256 and style) and the pins in media/release.sha256, and removes
//     the placeholders; committing them (git add -f: the plates are gitignored for the public export) puts the set in
//     the next image.
// ffmpeg runs bit-exact: no encoder tag (a "Lavc…" comment) in the files, so the bytes depend only on the input.
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { copyFileSync, existsSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";

const dir = new URL("../media/", import.meta.url);
const sha256 = (b: Buffer) => createHash("sha256").update(b).digest("hex");
const ff = (args: string[]) => execFileSync("ffmpeg", ["-v", "error", "-y", ...args.slice(0, -1), "-fflags", "+bitexact", "-flags:v", "+bitexact", ...args.slice(-1)]);
const at = (p: string) => new URL(p, dir).pathname;
const clear = (sub: string, re: RegExp) => { for (const f of readdirSync(new URL(sub, dir)).filter((f) => re.test(f))) rmSync(new URL(`${sub}${f}`, dir)); };
const N = 24;

if (process.argv[2] === "--placeholder") {
  const src = process.argv[3];
  if (!src) throw new Error("usage: node scripts/plates.ts --placeholder <dna-logo.mp4>");
  clear("plates/", /\.(jpg|png|json)$/);
  clear("references/", /^placeholder-.*\.(png|jpg)$/);
  const files: string[] = [];
  for (let i = 0; i < N; i++) {
    const file = `placeholder-${String(i + 1).padStart(2, "0")}.jpg`;
    const x = [96, 336, 576][i % 3]; // the helix left, centre or right of the frame
    ff(["-ss", String(i * 1.5), "-i", src, "-frames:v", "1", "-vf", `scale=864:864:flags=lanczos,pad=1536:864:${x}:0:color=0x020405`, "-q:v", "3", "-map_metadata", "-1", at(`plates/${file}`)]);
    files.push(file);
  }
  for (let i = 0; i < 6; i++) ff(["-ss", String(3 + i * 5.5), "-i", src, "-frames:v", "1", "-vf", "scale=1024:1024:flags=lanczos", "-q:v", "3", "-map_metadata", "-1", at(`references/placeholder-ref-${i + 1}.jpg`)]); // JPEG ≈ q90
  writeFileSync(at("plates/manifest.json"), `${JSON.stringify({ placeholder: true, source: "frames of the logo loop (media/dna-logo.mp4), scripts/plates.ts --placeholder", plates: files.map((file) => ({ file, sha256: sha256(readFileSync(at(`plates/${file}`))) })) }, null, 2)}\n`);
} else if (process.argv[2] === "--live") {
  if (!process.env.OPENAI_API_KEY) throw new Error("OPENAI_API_KEY unset (pass it in the env, never as an argument)");
  const work = join(tmpdir(), "dna-plates");
  // the studio's state in this run's own directory; 3 rounds of 1 candidate per plate at most, counted per run (a
  // same-day re-run starts from 0; the near-duplicate hashes stay, so a re-run never repeats a kept plate)
  Object.assign(process.env, { STUDIO_DIR: work, STUDIO_DAILY_ROUNDS: String(N * 3) });
  rmSync(join(work, `rounds-${new Date().toISOString().slice(0, 10)}.json`), { force: true });
  const studio = await import("../src/studio.ts");
  const { STYLES } = await import("../src/media-slots.ts");
  Object.assign(studio.STUDIO, studio.PLATE_RUN);
  const styles = STYLES.filter((s) => s !== "meme");
  const plates: { file: string; style: string }[] = [];
  const failed: string[] = [];
  for (const [k, style] of styles.entries()) {
    for (let j = 0; j < N / styles.length; j++) {
      const file = `plate-${style}-${j + 1}.jpg`;
      plates.push({ file, style });
      if (existsSync(at(`plates/${file}`))) continue; // kept from an earlier run
      const key = `plate:${style}:${j}`;
      const slots = { event: "outcome" as const, style, growth: 0.5, decay: 0, light: 0.5, seed: k * 100 + j };
      const meta = await studio.generate(key, slots, "wide", studio.activeClient(), (round) => studio.promptOf(slots, round, studio.PLATE_SCENES[j % studio.PLATE_SCENES.length]));
      if (meta.status !== "ready") { failed.push(`${file}: ${(meta.reasons ?? []).join("; ").slice(0, 300)}`); continue; }
      copyFileSync(join(work, `${createHash("sha256").update(key).digest("hex").slice(0, 32)}.art`), at(`plates/${file}`));
      console.error(`plates: ${file}`);
    }
  }
  if (failed.length) throw new Error(`${failed.length} of ${N} plates did not pass (run again: the passing ones are kept):\n${failed.join("\n")}`);
  clear("plates/", /^placeholder-.*\.jpg$/);
  const entries = plates.map(({ file, style }) => ({ file, sha256: sha256(readFileSync(at(`plates/${file}`))), style }));
  writeFileSync(at("plates/manifest.json"), `${JSON.stringify({ placeholder: false, source: `${studio.STUDIO.model} via scripts/plates.ts --live`, plates: entries }, null, 2)}\n`);
  // the release pins: every other file's line as it was, the plates' replaced
  const others = readFileSync(at("release.sha256"), "utf8").split("\n").filter((l) => l.trim() && !/\splates\//.test(l));
  const lines = [...others, ...entries.map((e) => `${e.sha256}  plates/${e.file}`)].sort((a, b) => a.split(/\s+/)[1].localeCompare(b.split(/\s+/)[1]));
  writeFileSync(at("release.sha256"), `${lines.join("\n")}\n`);
  console.error(`plates: ${N} plates written; the manifest and media/release.sha256 updated`);
} else throw new Error("usage: node scripts/plates.ts --placeholder <dna-logo.mp4> | --live");
